// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Exercises record-cache replay and rollback of growing TripleStore transactions.
 */
class TripleStoreGrowthAtomicityTest {

	private static final int GROWTH_ROWS = 32_768;
	private static final long OLD_SUBJECT = 1L;
	private static final long OLD_PREDICATE = 2L;
	private static final long OLD_OBJECT = 3L;
	private static final long OLD_CONTEXT = 10L;
	private static final long KEEP_SUBJECT = 4L;
	private static final long KEEP_PREDICATE = 2L;
	private static final long KEEP_OBJECT = 5L;
	private static final long KEEP_CONTEXT = 10L;
	private static final long PROMOTED_SUBJECT = 6L;
	private static final long PROMOTED_PREDICATE = 2L;
	private static final long PROMOTED_OBJECT = 7L;
	private static final long PROMOTED_CONTEXT = 11L;
	private static final long NEW_SUBJECT = 8L;
	private static final long NEW_PREDICATE = 2L;
	private static final long NEW_OBJECT = 9L;
	private static final long NEW_CONTEXT = 12L;

	@TempDir
	Path dataDir;

	@Test
	@Timeout(60)
	void growingCommitReplaysOverlayOperationsWithExactContextTotals() throws Exception {
		File storeDir = dataDir.resolve("successful").toFile();
		try (TripleStore store = new TripleStore(storeDir, growingConfig(), null)) {
			seed(store);
			store.startTransaction();
			addGrowthRows(store);
			applyOverlayOperations(store);
			store.commit();

			assertEquals(GROWTH_ROWS + 3, countAll(store, true),
					"the successful growing transaction must publish every final explicit row exactly once");
			assertEquals(0, countAll(store, false), "promotion must not leave an inferred duplicate");
			assertFinalState(store);
		}

		try (TripleStore reopened = new TripleStore(storeDir, growingConfig(), null)) {
			assertFinalState(reopened);
			removeAllRows(reopened);
			assertEmptyState(reopened);
		}

		try (TripleStore reopened = new TripleStore(storeDir, growingConfig(), null)) {
			assertEmptyState(reopened);
		}
	}

	@Test
	@Timeout(60)
	void rollbackAfterGrowthDoesNotPublishOverlayOrContextChanges() throws Exception {
		try (TripleStore store = new TripleStore(dataDir.resolve("rollback").toFile(), growingConfig(), null)) {
			seed(store);
			store.startTransaction();
			addGrowthRows(store);
			applyOverlayOperations(store);
			store.rollback();

			assertSeedState(store);
		}
	}

	@Test
	@Timeout(60)
	void patternRemovalSeesAddsMadeAfterTheRecordCacheWasActivated() throws Exception {
		try (TripleStore store = new TripleStore(dataDir.resolve("pattern-removal").toFile(), growingConfig(), null)) {
			seed(store);
			store.startTransaction();
			addGrowthRows(store);
			assertTrue(store.storeTriple(50_000L, 51L, 52L, 53L, true));
			store.removeTriplesByContext(-1, -1, -1, -1, true, ignored -> {
			});
			store.commit();

			assertEquals(0, countAll(store, true), "pattern removal must include rows retained only in the live cache");
			assertEquals(1, countAll(store, false));
			assertEquals(Map.of(PROMOTED_CONTEXT, 1), contextCounts(store));
		}
	}

	@Test
	@Timeout(60)
	void precommitFailureAfterGrowthLeavesThePreexistingModel() throws Exception {
		File storeDir = dataDir.resolve("precommit-failure").toFile();
		TripleStore store = new TripleStore(storeDir, growingConfig(), null);
		AtomicInteger physicalCommitCalls = new AtomicInteger();
		try {
			seed(store);
			store.startTransaction();
			addGrowthRows(store);
			store.beforePhysicalCommitForTest = () -> {
				physicalCommitCalls.incrementAndGet();
				throw new IllegalStateException("injected precommit failure");
			};
			applyOverlayOperations(store);

			IllegalStateException failure = assertThrows(IllegalStateException.class, store::commit);
			assertEquals("injected precommit failure", failure.getMessage());
			assertTrue(physicalCommitCalls.get() >= 1, "the failure must occur at a physical commit boundary");
		} finally {
			store.beforePhysicalCommitForTest = null;
			store.close();
		}

		try (TripleStore reopened = new TripleStore(storeDir, growingConfig(), null)) {
			assertSeedState(reopened);
		}
	}

	@Test
	@Timeout(60)
	void fixedMapPropagatesNativeMapFullAndRollbackKeepsThePreexistingModel() throws Exception {
		File storeDir = dataDir.resolve("fixed-map").toFile();
		LmdbStoreConfig config = growingConfig().setAutoGrow(false).setTripleDBSize(256L * 1024);
		try (TripleStore store = new TripleStore(storeDir, config, null)) {
			seed(store);
			assertSeedState(store);

			store.startTransaction();
			IOException failure = assertThrows(IOException.class, () -> {
				for (int i = 0; i < 100_000; i++) {
					assertTrue(store.storeTriple(1_000_000L + i, 30L + i % 5, 2_000_000L + i,
							40L + i % 3, true));
				}
			});
			assertTrue(failure.getMessage() != null && failure.getMessage().contains("MDB_MAP_FULL"),
					"a fixed map must expose the native capacity error instead of retrying a poisoned writer");

			store.rollback();
			assertSeedState(store);
		}

		try (TripleStore reopened = new TripleStore(storeDir, config, null)) {
			assertSeedState(reopened);
		}
	}

	private static LmdbStoreConfig growingConfig() {
		return new LmdbStoreConfig("spoc,posc")
				.setAutoGrow(true)
				.setForceSync(true)
				.setTripleDBSize(256L * 1024);
	}

	private static void seed(TripleStore store) throws IOException {
		store.startTransaction();
		assertTrue(store.storeTriple(OLD_SUBJECT, OLD_PREDICATE, OLD_OBJECT, OLD_CONTEXT, true));
		assertTrue(store.storeTriple(KEEP_SUBJECT, KEEP_PREDICATE, KEEP_OBJECT, KEEP_CONTEXT, true));
		assertTrue(store.storeTriple(PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT, false));
		store.commit();
	}

	private static void addGrowthRows(TripleStore store) throws IOException {
		for (int i = 0; i < GROWTH_ROWS; i++) {
			assertTrue(store.storeTriple(100_000L + i, 20L + i % 5, 200_000L + i, 20L + i % 3, true));
		}
	}

	private static void applyOverlayOperations(TripleStore store) throws IOException {
		long[] old = { OLD_SUBJECT, OLD_PREDICATE, OLD_OBJECT, OLD_CONTEXT };
		remove(store, old);
		assertTrue(store.storeTriple(OLD_SUBJECT, OLD_PREDICATE, OLD_OBJECT, OLD_CONTEXT, true));
		remove(store, old);

		long[] newRecord = { NEW_SUBJECT, NEW_PREDICATE, NEW_OBJECT, NEW_CONTEXT };
		assertTrue(store.storeTriple(NEW_SUBJECT, NEW_PREDICATE, NEW_OBJECT, NEW_CONTEXT, true));
		remove(store, newRecord);
		assertTrue(store.storeTriple(NEW_SUBJECT, NEW_PREDICATE, NEW_OBJECT, NEW_CONTEXT, true));

		assertTrue(store.storeTriple(PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT, true));
	}

	private static void remove(TripleStore store, long[] quad) throws IOException {
		store.removeTriples(singleQuad(quad), true, ignored -> {
		});
	}

	private static RecordIterator singleQuad(long[] quad) {
		return new RecordIterator() {
			private boolean emitted;

			@Override
			public long[] next() {
				if (emitted) {
					return null;
				}
				emitted = true;
				return quad.clone();
			}

			@Override
			public void close() {
				emitted = true;
			}
		};
	}

	private static void assertFinalState(TripleStore store) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			assertEquals(0, count(store.getTriples(txn, OLD_SUBJECT, OLD_PREDICATE, OLD_OBJECT, OLD_CONTEXT, true)));
			assertEquals(1, count(store.getTriples(txn, NEW_SUBJECT, NEW_PREDICATE, NEW_OBJECT, NEW_CONTEXT, true)));
			assertEquals(1,
					count(store.getTriples(txn, PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT,
							true)));
			assertEquals(0,
					count(store.getTriples(txn, PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT,
							false)));
		}

		Map<Long, Integer> expected = expectedFinalContextCounts();
		assertEquals(expected, contextCounts(store));
	}

	private static void removeAllRows(TripleStore store) throws IOException {
		store.startTransaction();
		store.removeTriplesByContext(-1, -1, -1, -1, true, ignored -> {
		});
		store.removeTriplesByContext(-1, -1, -1, -1, false, ignored -> {
		});
		store.commit();
	}

	private static void assertEmptyState(TripleStore store) throws IOException {
		assertEquals(0, countAll(store, true));
		assertEquals(0, countAll(store, false));
		assertEquals(Map.of(), contextCounts(store));
	}

	private static void assertSeedState(TripleStore store) throws IOException {
		assertEquals(2, countAll(store, true));
		assertEquals(1, countAll(store, false));
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			assertEquals(1, count(store.getTriples(txn, OLD_SUBJECT, OLD_PREDICATE, OLD_OBJECT, OLD_CONTEXT, true)));
			assertEquals(0, count(store.getTriples(txn, NEW_SUBJECT, NEW_PREDICATE, NEW_OBJECT, NEW_CONTEXT, true)));
			assertEquals(0,
					count(store.getTriples(txn, PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT,
							true)));
			assertEquals(1,
					count(store.getTriples(txn, PROMOTED_SUBJECT, PROMOTED_PREDICATE, PROMOTED_OBJECT, PROMOTED_CONTEXT,
							false)));
		}

		Map<Long, Integer> expected = new TreeMap<>();
		expected.put(OLD_CONTEXT, 2);
		expected.put(PROMOTED_CONTEXT, 1);
		assertEquals(expected, contextCounts(store));
	}

	private static Map<Long, Integer> expectedFinalContextCounts() {
		Map<Long, Integer> expected = new TreeMap<>();
		expected.put(KEEP_CONTEXT, 1);
		expected.put(PROMOTED_CONTEXT, 1);
		expected.put(NEW_CONTEXT, 1);
		for (int i = 0; i < GROWTH_ROWS; i++) {
			expected.merge(20L + i % 3, 1, Integer::sum);
		}
		return expected;
	}

	private static Map<Long, Integer> contextCounts(TripleStore store) throws IOException {
		Map<Long, Integer> counts = new TreeMap<>();
		try (Txn txn = store.getTxnManager().createReadTxn(); LmdbContextIdIterator contexts = store.getContexts(txn)) {
			long[] context;
			while ((context = contexts.next()) != null) {
				int explicit = count(store.getTriples(txn, -1, -1, -1, context[0], true));
				int inferred = count(store.getTriples(txn, -1, -1, -1, context[0], false));
				counts.put(context[0], explicit + inferred);
			}
		}
		return counts;
	}

	private static int countAll(TripleStore store, boolean explicit) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			return count(store.getTriples(txn, -1, -1, -1, -1, explicit));
		}
	}

	private static int count(RecordIterator records) throws IOException {
		int count = 0;
		try (records) {
			while (records.next() != null) {
				count++;
			}
		}
		return count;
	}
}
